// Signs what setlist-search returns, so log_concert can tell setlist.fm's details from ones a
// client made up (SECURITY_AUDIT.md, M1). The key is generated by the database
// (private.app_secrets) and read by the Edge Function with the service role.
//
// Must match private.lineup_signature() in supabase/migrations/*_security_hardening.sql:
// HMAC-SHA256 over the kind and the fields, each trimmed (null as ""), joined by \x1f.
import type { ConcertResult, FestivalDayResult, LineupArtist, SearchResult } from "./contract.ts";

export type Signer = (
  kind: "show" | "artist",
  fields: (string | null | undefined)[],
) => Promise<string>;

export async function createSigner(keyHex: string): Promise<Signer> {
  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(keyHex),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  return async (kind, fields) => {
    const message = [kind, ...fields.map((f) => (f ?? "").trim())].join("\x1f");
    const mac = new Uint8Array(await crypto.subtle.sign("HMAC", key, encoder.encode(message)));
    return Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("");
  };
}

type UnsignedResult = Omit<ConcertResult, "signature"> | Omit<FestivalDayResult, "signature">;

/** The show a search result would be logged as: venue, date, festival name and day label. */
export function signResult(result: UnsignedResult, sign: Signer): Promise<SearchResult> {
  const festival = result.kind === "festival-day" ? result : null;
  return sign("show", [
    result.venue.setlistfmId,
    result.venue.name,
    result.venue.city,
    result.venue.state,
    result.date,
    festival?.festivalName,
    festival?.dayLabel,
  ]).then((signature) => ({ ...result, signature }) as SearchResult);
}

/** One lineup artist at the show on `date`: MBID, name and setlist.fm links. */
export function signArtist(
  artist: Omit<LineupArtist, "signature">,
  date: string,
  sign: Signer,
): Promise<LineupArtist> {
  return sign("artist", [
    artist.mbid,
    artist.name,
    artist.setlistfmUrl,
    artist.setlistUrl,
    date,
  ]).then((signature) => ({ ...artist, signature }));
}
